24	            if (city.equalsIgnoreCase(existing.getCity())) {
25	                count++;
26	            }
27	        }
28	        if (count >= CITY_CAPACITY) {
29	            throw new CityAtCapacityException(
30	                    "City " + city + " already contains " + CITY_CAPACITY + " or more owners");
