8	/**
9	 * Runs after the {@link ValidateUniqueHousehold} gate and before {@link BuildOwner}, under
10	 * {@code govern: [ transaction ]}. When the gate resolved a shared {@link Household.Id} (the new
11	 * owner is joining an existing household), back-fills that identifier onto every existing member
12	 * that is missing it, so the whole household carries the same stable id. A no-op — publishing
13	 * nothing and touching no rows — when the new owner is not joining a shared household.
14	 */
15	public class ApplySharedHousehold {
16	
17	    public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
18	            OwnerRepository ownerRepository) {
19	        if (householdId == null || !householdId.isPresent()) {
20	            return;
21	        }
22	        for (Owner member : Household.membersOf(request, ownerRepository)) {
23	            if (!householdId.value().equals(member.getHouseholdId())) {
24	                member.setHouseholdId(householdId.value());
25	                ownerRepository.save(member);
26	            }
27	        }
28	    }
29	}
