1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	
14	/**
15	 * Shared household rules for the owner-create pipeline. A household is the set of owners with
16	 * the same last name at the same address, compared case-insensitively with collapsed
17	 * whitespace. The membership match and the stable identifier are defined once here so the gate
18	 * ({@link ValidateUniqueHousehold}), the back-fill ({@link ApplySharedHousehold}) and the new
19	 * owner ({@link BuildOwner}) all agree on them.
20	 */
21	final class Household {
22	
23	    private Household() {
24	    }
25	
26	    /**
27	     * The household identifier published between steps. A dedicated type keeps the variable
28	     * unambiguous (OfficeFloor matches variables by type) and distinct from other strings in
29	     * the pipeline. {@link #ABSENT} (an empty value) means the new owner is not joining a
30	     * shared household.
31	     */
32	    record Id(String value) {
33	
34	        static final Id ABSENT = new Id("");
35	
36	        boolean isPresent() {
37	            return this.value != null && !this.value.isBlank();
38	        }
39	    }
40	
41	    /**
42	     * Existing owners that share the request's household (same normalized last name and
43	     * address).
44	     */
45	    static List<Owner> membersOf(OwnerFieldsDto request, OwnerRepository ownerRepository) {
46	        String lastName = normalize(request.getLastName());
47	        String address = OwnerAddress.normalize(request.getAddress());
48	        List<Owner> members = new ArrayList<>();
49	        for (Owner existing : ownerRepository.findAll()) {
50	            if (lastName.equals(normalize(existing.getLastName()))
51	                    && address.equals(OwnerAddress.normalize(existing.getAddress()))) {
52	                members.add(existing);
53	            }
54	        }
55	        return members;
56	    }
57	
58	    /**
59	     * Stable identifier for the request's household: the first 12 upper-case hex characters of
60	     * the SHA-256 of the normalized last name and address, so every owner in the same household
61	     * derives the same value regardless of creation order.
62	     */
63	    static Id idFor(OwnerFieldsDto request) {
64	        String seed = normalize(request.getLastName()) + "\n" + OwnerAddress.normalize(request.getAddress());
65	        try {
66	            byte[] digest = MessageDigest.getInstance("SHA-256")
67	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
68	            StringBuilder sb = new StringBuilder();
69	            for (int i = 0; i < 6; i++) {
70	                sb.append(String.format("%02X", digest[i]));
71	            }
72	            return new Id(sb.toString());
73	        }
74	        catch (NoSuchAlgorithmException ex) {
75	            throw new IllegalStateException("SHA-256 not available", ex);
76	        }
77	    }
78	
79	    /**
80	     * Normalize a name or address for household comparison: trim, collapse any run of
81	     * whitespace to a single space, and lower-case. Yields {@code ""} for a {@code null} input.
82	     */
83	    private static String normalize(String value) {
84	        if (value == null) {
85	            return "";
86	        }
87	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
88	    }
89	}
