5	/**
6	 * Registration-date business-day rule. The effective registration date — whether it was
7	 * supplied in the request or defaulted to the server's current date — must fall on a
8	 * business day: a Saturday or Sunday rolls forward to the following Monday. Applied
9	 * wherever the registration date is derived ({@link BuildOwner}) or compared
10	 * ({@link ValidateDailyOwnerLimit}) so both agree on the same adjusted day.
11	 */
12	final class BusinessDay {
13	
14	    private BusinessDay() {
15	    }
16	
17	    /** Roll a weekend date forward to the next Monday; a weekday is returned unchanged. */
18	    static LocalDate rollForward(LocalDate date) {
19	        return switch (date.getDayOfWeek()) {
20	            case SATURDAY -> date.plusDays(2);
21	            case SUNDAY -> date.plusDays(1);
22	            default -> date;
23	        };
24	    }
25	
26	    /**
27	     * The effective, business-day-adjusted registration date: the supplied date when
28	     * present, otherwise the server's current date, rolled forward off any weekend.
29	     */
30	    static LocalDate effectiveRegistrationDate(LocalDate supplied) {
31	        return rollForward(supplied != null ? supplied : LocalDate.now());
32	    }
33	}
